and r.status=#{status}
and h.scope=#{scope}
and h.type_id=#{type}
and coalesce(h.agent_id,(select s.agent_id from agent_runtime_memory_fact_sources s
        where s.tenant_id=h.tenant_id and s.fact_id=h.fact_id and s.revision=r.content_revision
        order by s.source_ordinal limit 1))=#{agent}
and coalesce(h.end_user_id,o.end_user_id)=#{endUser}
order by r.created_epoch_second desc,r.created_nano desc limit #{limit}

mapper.insert:
insert into public.nw_runtime_memory_governance_receipts
    (tenant_id,request_key,fact_id,expected_revision,operation,request_fingerprint)
select #{request.tenantId},#{key},#{request.factId},#{request.expectedRevision},#{request.operation},#{request.fingerprint}
  from public.agent_runtime_memory_fact_revisions
 where tenant_id=#{request.tenantId} and fact_id=#{request.factId} and revision=#{request.expectedRevision}
on conflict (tenant_id,request_key) do nothing

mapper.select:
select request_key,fact_id,expected_revision,operation,request_fingerprint,accepted_at
  from public.nw_runtime_memory_governance_receipts
 where tenant_id=#{tenant} and request_key=#{key}
